SELECT name, setting, source, sourcefile
  FROM pg_settings
 WHERE name = 'track_io_timing';

CREATE TABLE customers (
    customer_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    full_name    text NOT NULL,
    city         text NOT NULL
);

CREATE TABLE orders (
    order_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id  bigint NOT NULL REFERENCES customers,
    status       text NOT NULL,
    amount       numeric(10,2) NOT NULL,
    created_at   timestamptz NOT NULL
);

INSERT INTO customers (full_name, city)
SELECT 'Customer ' || g,
       (ARRAY['Hyderabad','Pune','Chennai','Bengaluru'])[1 + g % 4]
  FROM generate_series(1, 5000) AS g;

INSERT INTO orders (customer_id, status, amount, created_at)
SELECT 1 + g % 5000,
       (ARRAY['new','paid','shipped','cancelled'])[1 + g % 4],
       round((random() * 5000)::numeric, 2),
       now() - g * interval '1 minute'
  FROM generate_series(1, 200000) AS g;

CREATE INDEX orders_customer_id_idx ON orders (customer_id);
CREATE INDEX orders_created_at_idx  ON orders (created_at);
ANALYZE;

sudo -u postgres tee /var/lib/postgresql/shop_workload.sql > /dev/null <<'EOF'
\set cid random(1, 5000)
SELECT count(*) FROM orders WHERE customer_id = :cid;
SELECT order_id, amount FROM orders WHERE status = 'new' AND amount > 4990;
UPDATE orders SET status = 'paid' WHERE order_id = :cid * 40;
SELECT full_name, city FROM customers WHERE customer_id = :cid;
EOF

SET work_mem = '1MB';
SELECT customer_id, sum(amount) AS total
  FROM orders
 GROUP BY customer_id
 ORDER BY total DESC
 LIMIT 3;

BEGIN;
DELETE FROM orders WHERE status = 'cancelled';
ROLLBACK;

